        m = random.randint(n, n * 2)
        cnf = generate_cnf(n, m)
        H = hamiltonian_matrix(cnf)
        norm_H = min_quaternionic_norm(H)
        w_C = monotone_width(cnf)
        results.append((norm_H, w_C))

    if not results:
